#!/usr/bin/env python3
"""Mirror verified public release assets onto a dedicated browser-readable branch."""
# AI: below section was generated by an AI
import argparse
import json
import os
import shutil
import subprocess
import tempfile
import urllib.request
from pathlib import Path
from icon256_release import verify, validate_repository, version_from_tag


def fetch(url, limit):
    request = urllib.request.Request(url, headers={'User-Agent': 'Icon256-update-feed'})
    # Authenticate only repository API calls on CI; never forward the token to assets or redirects.
    token = os.environ.get('GH_TOKEN')
    if token and url.startswith('https://api.github.com/repos/ThingPulse/WLED-Icon256/'):
        request.add_unredirected_header('Authorization', 'Bearer ' + token)
    with urllib.request.urlopen(request, timeout=60) as response:
        data = response.read(limit + 1)
    if len(data) > limit:
        raise ValueError('Release asset exceeds limit')
    return data


def build_feed(repository, checkout):
    """Use a disposable authenticated checkout; retain immutable commits for each version."""
    validate_repository(repository)
    if repository != 'ThingPulse/WLED-Icon256':
        raise ValueError('Unexpected update repository')
    def git(*args):
        return subprocess.check_output(['git', '-C', str(checkout), *args], text=True).strip()
    branch = 'icon256-updates'
    remote = git('ls-remote', '--heads', 'origin', branch)
    if remote:
        git('fetch', 'origin', branch)
        git('checkout', '-B', branch, 'FETCH_HEAD')
    else:
        git('checkout', '--orphan', branch)
        git('rm', '-rf', '--ignore-unmatch', '.')
    releases = json.loads(fetch(f'https://api.github.com/repos/{repository}/releases?per_page=100', 2_000_000))
    if not isinstance(releases, list):
        raise ValueError('Invalid releases response')
    old_path = checkout/'catalog.json'
    old = json.loads(old_path.read_text())['releases'] if old_path.exists() else []
    entries = []
    with tempfile.TemporaryDirectory() as tmp:
        for release in releases:
            if release['draft'] or not release['published_at']:
                continue
            tag = release['tag_name']
            try:
                version, prerelease = version_from_tag(tag)
            except ValueError:
                continue
            if prerelease != release['prerelease']:
                raise ValueError('Release channel differs from version')
            names = {'manifest.json', 'SHA256SUMS', f'WLED_{version}_ESP32_S3_Icon256.bin'}
            assets = {a['name']: a for a in release['assets']}
            if not names <= assets.keys():
                continue  # Incomplete releases never enter the update feed.
            stage = Path(tmp)/tag
            stage.mkdir()
            for name in names:
                expected = f'https://github.com/{repository}/releases/download/{tag}/{name}'
                if assets[name]['browser_download_url'] != expected:
                    raise ValueError('Unexpected release asset URL')
                (stage/name).write_bytes(fetch(expected, 0x180000 if name.endswith('.bin') else 65536))
            verify(stage/'manifest.json')
            manifest = json.loads((stage/'manifest.json').read_text())
            if manifest['repository'] != repository or manifest['tag'] != tag:
                raise ValueError('Release manifest identity mismatch')
            destination = checkout/tag
            existing = next((e for e in old if e['tag'] == tag), None)
            if existing:
                if any(not (destination/n).exists() or (destination/n).read_bytes() != (stage/n).read_bytes() for n in names):
                    raise ValueError('Published release assets changed; use a new version')
                entries.append(existing)
                continue
            shutil.copytree(stage, destination, dirs_exist_ok=True)
            git('add', '--', tag)
            git('commit', '-m', f'Mirror verified Icon256 {version} assets')
            entries.append({'tag': tag, 'version': version, 'commit': git('rev-parse', 'HEAD')})
    catalog = {'schema_version': 1, 'repository': repository, 'releases': entries}
    old_path.write_text(json.dumps(catalog, indent=2) + '\n')
    git('add', 'catalog.json')
    if git('diff', '--cached', '--name-only'):
        git('commit', '-m', 'Update published Icon256 firmware catalog')
    git('push', 'origin', f'HEAD:refs/heads/{branch}')
    print(f'Published update catalog: {len(entries)} verified releases')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repository', required=True)
    parser.add_argument('--checkout', type=Path, required=True)
    args = parser.parse_args()
    build_feed(args.repository, args.checkout.resolve())
# AI: end
